"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Box,
  CardActionArea,
  Chip,
  Stack,
  Tab,
  Tabs,
  Typography
} from "@mui/material";
import type { LabelFormat } from "../../lib/label-format-registry";

type FormatCategory = {
  id: string;
  label: string;
};

export function LabelFormatSelector({
  categories,
  formats,
  value,
  onChange
}: {
  categories: readonly FormatCategory[];
  formats: LabelFormat[];
  value: string;
  onChange: (nextId: string) => void;
}) {
  const selectedFormat = useMemo(
    () => formats.find((format) => format.id === value) ?? formats[0] ?? null,
    [formats, value]
  );
  const [activeCategory, setActiveCategory] = useState<string>(
    selectedFormat?.category ?? categories[0]?.id ?? "all"
  );

  useEffect(() => {
    if (selectedFormat?.category) {
      setActiveCategory(selectedFormat.category);
    }
  }, [selectedFormat?.category]);

  const visibleFormats = useMemo(
    () => formats.filter((format) => format.category === activeCategory),
    [activeCategory, formats]
  );

  return (
    <Stack spacing={2}>
      <Tabs
        value={activeCategory}
        onChange={(_, nextValue: string) => setActiveCategory(nextValue)}
        variant="scrollable"
        scrollButtons="auto"
        allowScrollButtonsMobile
      >
        {categories.map((category) => (
          <Tab key={category.id} value={category.id} label={category.label} />
        ))}
      </Tabs>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "repeat(1, minmax(0, 1fr))",
            sm: "repeat(2, minmax(0, 1fr))"
          },
          gap: 1.5
        }}
      >
        {visibleFormats.map((format) => {
          const active = format.id === value;

          return (
            <Box
              key={format.id}
              sx={{
                borderRadius: 2.5,
                overflow: "hidden",
                border: active
                  ? "1px solid rgba(15, 118, 110, 0.24)"
                  : "1px solid rgba(15, 23, 42, 0.08)",
                background: active ? "rgba(15, 118, 110, 0.08)" : "#fff"
              }}
            >
              <CardActionArea onClick={() => onChange(format.id)} sx={{ p: 1.75 }}>
                <Stack spacing={0.9}>
                  <Stack direction="row" spacing={1} sx={{ justifyContent: "space-between" }}>
                    <Typography variant="subtitle2" sx={{ color: active ? "primary.main" : "text.primary" }}>
                      {format.name}
                    </Typography>
                    <Chip
                      size="small"
                      variant={active ? "filled" : "outlined"}
                      color={active ? "primary" : "default"}
                      label={format.shape}
                    />
                  </Stack>
                  <Typography variant="body2" color="text.secondary">
                    {format.widthMm} x {format.heightMm} mm
                  </Typography>
                  {format.description ? (
                    <Typography variant="caption" color="text.secondary">
                      {format.description}
                    </Typography>
                  ) : null}
                </Stack>
              </CardActionArea>
            </Box>
          );
        })}
      </Box>
    </Stack>
  );
}
