"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Autocomplete,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
  Typography
} from "@mui/material";
import LocalPrintshopRoundedIcon from "@mui/icons-material/LocalPrintshopRounded";
import BookmarkBorderRoundedIcon from "@mui/icons-material/BookmarkBorderRounded";
import type { LabelDocument } from "@easyprint/shared/template/document";
import {
  buildPreviewPayload,
  type PreviewPayload
} from "@easyprint/shared/template/render";
import { DashboardShell } from "../../components/app/dashboard-shell";
import { SessionGuard } from "../../components/app/session-guard";
import { LabelPreviewSurface } from "../../components/editor/label-preview-surface";
import { LabelPrintPortal } from "../../components/print/label-print-portal";
import { getScannableValidationErrors } from "../../lib/barcode-validation";
import { LabelFormatSelector } from "../../components/ui/label-format-selector";
import { PageSection } from "../../components/ui/page-section";
import {
  fetchTemplateDocument,
  fetchProducts,
  fetchTemplates,
  type ProductItem,
  type TemplateListItem
} from "../../lib/api";
import {
  LABEL_FORMAT_CATEGORIES,
  LABEL_FORMATS,
  getDefaultLabelFormat,
  getLabelFormatById,
  type LabelFormat
} from "../../lib/label-format-registry";
import { getDefaultQuickForm, type QuickLabelForm } from "../../lib/quick-label-builder";
import {
  buildOfficialTemplateDocument,
  buildOfficialTemplatePreviewPayload,
  listOfficialTemplatePresetOptions
} from "../../lib/official-template-presets";
import type { OfficialTemplateId } from "../../lib/official-template-catalog";
import { sessionHasPermission, type ApiSession } from "../../lib/session";
import {
  buildQuickPrintPayload,
  inferTemplateCategory
} from "../../lib/template-library";

const formatDateLabel = (value: string) =>
  new Date(`${value}T00:00:00`).toLocaleDateString("pt-BR");

const formatTimeLabel = () =>
  new Date().toLocaleTimeString("pt-BR", {
    hour: "2-digit",
    minute: "2-digit"
  });

const ORIGIN_FOOTER =
  "Pascal Fast Food.\nRua Victorio Viezzer, 588.\nVista Alegre.\nCuritiba - Parana.";
const ORIGIN_VERTICAL_TEXT =
  "Pascal Fast Food.\nRua Victorio Viezzer, 588.\nVista Alegre.\nCuritiba-Paraná.";

const OFFICIAL_TEMPLATE_OPTIONS = listOfficialTemplatePresetOptions().filter(
  (template) => template.operationKind === "unit"
);

const DEFAULT_TEMPLATE_ID: OfficialTemplateId = "template_60x40_unidade_vertical";

const formatTimestampLabel = (value: string) =>
  new Date(value).toLocaleString("pt-BR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit"
  });

const formatTemplateTypeLabel = (template: TemplateListItem) => {
  const format =
    typeof template.formatId === "string" ? getLabelFormatById(template.formatId) : undefined;

  if (format) {
    return format.name;
  }

  if (template.width && template.height && template.unit) {
    return `${template.width} x ${template.height} ${template.unit}`;
  }

  return "Formato personalizado";
};

const formatTemplateCategoryLabel = (template: TemplateListItem) =>
  template.category
    ? `${template.category.charAt(0).toUpperCase()}${template.category.slice(1)}`
    : "Categoria livre";

const formatCurrencyLabel = (value?: number | null) =>
  typeof value === "number" && Number.isFinite(value)
    ? new Intl.NumberFormat("pt-BR", {
        style: "currency",
        currency: "BRL"
      }).format(value)
    : null;

const buildProductOptionMeta = (product: ProductItem) => {
  const tokens = [
    product.productCode ? `Codigo: ${product.productCode}` : null,
    product.barcode ? `Barcode: ${product.barcode}` : null,
    product.category ? `Categoria: ${product.category}` : null,
    product.unitOfMeasure ? product.unitOfMeasure : null,
    formatCurrencyLabel(product.price)
  ].filter(Boolean);

  return tokens.join(" — ");
};

export default function HomePage() {
  const [session, setSession] = useState<ApiSession | null>(null);

  return (
    <SessionGuard onSession={setSession}>
      <DashboardShell
        title="Operacao Rapida"
        subtitle="Preencha responsavel, item e quantidade. O restante da etiqueta e resolvido automaticamente."
      >
        <QuickWelcomeExperience session={session} />
      </DashboardShell>
    </SessionGuard>
  );
}

const getProductOptionKey = (product: ProductItem) =>
  product.id ||
  product.productCode ||
  product.barcode ||
  `${product.name}-${product.productCode ?? "sem-codigo"}-${product.barcode ?? "sem-barcode"}`;

function QuickWelcomeExperience({ session }: { session: ApiSession | null }) {
  const [form, setForm] = useState<QuickLabelForm>(getDefaultQuickForm());
  const [printActive, setPrintActive] = useState(false);
  const [formatDialogOpen, setFormatDialogOpen] = useState(false);
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
  const [savedTemplateDialogOpen, setSavedTemplateDialogOpen] = useState(false);
  const [templateId, setTemplateId] = useState<OfficialTemplateId>(DEFAULT_TEMPLATE_ID);
  const [savedTemplates, setSavedTemplates] = useState<TemplateListItem[]>([]);
  const [savedTemplatesLoading, setSavedTemplatesLoading] = useState(false);
  const [savedTemplatesError, setSavedTemplatesError] = useState<string | null>(null);
  const [savedTemplateLoadingId, setSavedTemplateLoadingId] = useState<string | null>(null);
  const [products, setProducts] = useState<ProductItem[]>([]);
  const [productsLoading, setProductsLoading] = useState(false);
  const [productsError, setProductsError] = useState<string | null>(null);
  const [productSearch, setProductSearch] = useState("");
  const [debouncedProductSearch, setDebouncedProductSearch] = useState("");
  const [selectedProduct, setSelectedProduct] = useState<ProductItem | null>(null);
  const [selectedSavedTemplateId, setSelectedSavedTemplateId] = useState<string | null>(null);
  const [selectedSavedTemplateDocument, setSelectedSavedTemplateDocument] =
    useState<LabelDocument | null>(null);

  const selectedFormat: LabelFormat = useMemo(
    () => getLabelFormatById(form.formatId) ?? getDefaultLabelFormat(),
    [form.formatId]
  );

  const selectedTemplate = useMemo(
    () =>
      OFFICIAL_TEMPLATE_OPTIONS.find((template) => template.id === templateId) ??
      OFFICIAL_TEMPLATE_OPTIONS[0],
    [templateId]
  );

  const templatePreviewSamples = useMemo(
    () =>
      Object.fromEntries(
        OFFICIAL_TEMPLATE_OPTIONS.map((template) => {
          const formatId =
            template.defaultFormat?.id ?? template.recommendedFormats[0]?.id ?? form.formatId;
          const previewDocument = buildOfficialTemplateDocument({
            templateId: template.id,
            formatId,
            name: template.name
          });
          const previewPayload = buildOfficialTemplatePreviewPayload(template.id, {
            productName: "Sanduiche natural",
            productDescription: "Sanduiche natural",
            manufacturingDate: "09/04/2026",
            expirationDate: "11/04/2026",
            time: "14:30",
            quantity: "1",
            unitPrice: 12.9,
            totalPrice: 12.9,
            barcode: "7891234567890",
            barcodeText: "7891234567890",
            responsibleLabel: "Resp. Equipe:",
            responsibleName: "Equipe A",
            originFooter: ORIGIN_FOOTER,
            originVerticalText: ORIGIN_VERTICAL_TEXT
          });
          const scale = Math.min(
            2.2,
            132 / Math.max(previewDocument.document.width, 1),
            88 / Math.max(previewDocument.document.height, 1)
          );

          return [
            template.id,
            {
              document: previewDocument,
              previewPayload,
              scale
            }
          ];
        })
      ) as Record<
        OfficialTemplateId,
        {
          document: LabelDocument;
          previewPayload: PreviewPayload;
          scale: number;
        }
      >,
    [form.formatId]
  );

  const officialDocument = useMemo(
    () =>
      buildOfficialTemplateDocument({
        templateId,
        formatId: selectedFormat.id,
        name: selectedTemplate?.name
      }),
    [selectedFormat.id, selectedTemplate?.name, templateId]
  );

  const selectedSavedTemplate = useMemo(
    () => savedTemplates.find((template) => template.id === selectedSavedTemplateId) ?? null,
    [savedTemplates, selectedSavedTemplateId]
  );

  const document = selectedSavedTemplateDocument ?? officialDocument;

  const productDataPayload = useMemo(() => {
    const unitPrice = selectedProduct?.price ?? undefined;
    const totalPrice =
      unitPrice !== undefined && unitPrice !== null
        ? Number(unitPrice) * Math.max(1, Number(form.quantity) || 1)
        : undefined;
    const productName = selectedProduct?.name || form.product || "Produto";
    const barcode = selectedProduct?.barcode || form.barcode;

    return {
      productId: selectedProduct?.id,
      productName,
      product: productName,
      produto: productName,
      item: productName,
      productDescription: selectedProduct?.description || productName,
      description: selectedProduct?.description,
      descricao: selectedProduct?.description,
      ingredients: selectedProduct?.ingredients,
      ingredientes: selectedProduct?.ingredients,
      recipeLines: selectedProduct?.ingredients,
      unitPrice,
      price: unitPrice,
      preco: unitPrice,
      precoUnitario: unitPrice,
      totalPrice,
      total: totalPrice,
      barcode,
      barcodeText: barcode,
      productCode: selectedProduct?.productCode,
      codigoProduto: selectedProduct?.productCode,
      unitOfMeasure: selectedProduct?.unitOfMeasure,
      unidade: selectedProduct?.unitOfMeasure,
      category: selectedProduct?.category,
      brand: selectedProduct?.brand,
      origin: selectedProduct?.origin
    };
  }, [form.product, form.quantity, form.barcode, selectedProduct]);

  const previewPayload = useMemo(
    () => {
      if (selectedSavedTemplateDocument && selectedSavedTemplate) {
        const category = inferTemplateCategory({
          name: selectedSavedTemplate.name,
          category: selectedSavedTemplate.category
        });

        return {
          ...buildPreviewPayload(selectedSavedTemplateDocument),
          ...buildQuickPrintPayload(selectedSavedTemplateDocument, category, {
            productName: String(productDataPayload.productName),
            responsibleName: form.responsible || "Equipe",
            manufacturedAt: form.manufacturedAt,
            expiresAt: form.expiresAt,
            quantity: form.quantity
          }),
          responsibleLabel: "Resp. Equipe:",
          ...productDataPayload
        };
      }

      return buildOfficialTemplatePreviewPayload(templateId, {
        ...productDataPayload,
        productName: String(productDataPayload.productName),
        productDescription:
          typeof productDataPayload.productDescription === "string"
            ? productDataPayload.productDescription
            : String(productDataPayload.productName),
        manufacturingDate: formatDateLabel(form.manufacturedAt),
        expirationDate: formatDateLabel(form.expiresAt),
        time: formatTimeLabel(),
        quantity: String(form.quantity),
        barcode: String(productDataPayload.barcode || form.barcode),
        barcodeText: String(productDataPayload.barcode || form.barcode),
        responsibleLabel: "Resp. Equipe:",
        responsibleName: form.responsible || "Equipe",
        originFooter: ORIGIN_FOOTER,
        originVerticalText: ORIGIN_VERTICAL_TEXT
      });
    },
    [form, productDataPayload, selectedSavedTemplate, selectedSavedTemplateDocument, templateId]
  );

  const previewScale = useMemo(() => {
    const maxW = 440;
    const maxH = 340;
    return Math.min(
      6,
      maxW / Math.max(document.document.width, 1),
      maxH / Math.max(document.document.height, 1)
    );
  }, [document.document.height, document.document.width]);

  useEffect(() => {
    const timeoutId = window.setTimeout(() => {
      setDebouncedProductSearch(productSearch.trim());
    }, 250);

    return () => window.clearTimeout(timeoutId);
  }, [productSearch]);

  useEffect(() => {
    if (!session) {
      return;
    }

    let active = true;
    setSavedTemplatesLoading(true);
    setSavedTemplatesError(null);

    void fetchTemplates(session, { limit: 10 })
      .then((templates) => {
        if (!active) return;
        setSavedTemplates(
          templates.filter((template) => template.status !== "ARCHIVED").slice(0, 10)
        );
      })
      .catch(() => {
        if (!active) return;
        setSavedTemplatesError("Nao foi possivel carregar os templates salvos.");
      })
      .finally(() => {
        if (!active) return;
        setSavedTemplatesLoading(false);
      });

    return () => {
      active = false;
    };
  }, [session]);

  useEffect(() => {
    if (!session) {
      setProducts([]);
      setProductsError(null);
      return;
    }

    let active = true;
    setProductsLoading(true);
    setProductsError(null);

    void fetchProducts(session, {
      active: "true",
      search: debouncedProductSearch || undefined
    })
      .then((nextProducts) => {
        if (!active) return;
        setProducts(nextProducts);
      })
      .catch(() => {
        if (!active) return;
        setProducts([]);
        setProductsError("Nao foi possivel carregar os produtos da base.");
      })
      .finally(() => {
        if (!active) return;
        setProductsLoading(false);
      });

    return () => {
      active = false;
    };
  }, [debouncedProductSearch, session]);

  useEffect(() => {
    if (!printActive) return;

    let frame = 0;
    frame = window.requestAnimationFrame(() => {
      try {
        window.print();
      } catch {
        // O usuario pode tentar novamente.
      } finally {
        setPrintActive(false);
      }
    });

    return () => window.cancelAnimationFrame(frame);
  }, [printActive]);

  useEffect(() => {
    if (!selectedProduct) {
      return;
    }

    const refreshedProduct = products.find((product) => product.id === selectedProduct.id);
    if (refreshedProduct) {
      setSelectedProduct(refreshedProduct);
    }
  }, [products, selectedProduct]);

  const handleFieldChange = <TKey extends keyof QuickLabelForm>(
    key: TKey,
    value: QuickLabelForm[TKey]
  ) => {
    setForm((current) => ({
      ...current,
      [key]: value
    }));
  };

  const handleQuantityChange = (value: string) => {
    const parsed = Number(value);
    setForm((current) => ({
      ...current,
      quantity:
        Number.isFinite(parsed) && parsed >= 1 ? Math.max(1, Math.floor(parsed)) : 1
    }));
  };

  const handleProductSelection = (product: ProductItem | null) => {
    setSelectedProduct(product);
    setProductSearch(product?.name ?? "");
    if (!product) {
      return;
    }

    setForm((current) => ({
      ...current,
      product: product.name,
      barcode: product.barcode || current.barcode
    }));
  };

  const handleFormatChange = (value: string) => {
    setSelectedSavedTemplateId(null);
    setSelectedSavedTemplateDocument(null);
    setForm((current) => ({
      ...current,
      formatId: value
    }));
    setFormatDialogOpen(false);
  };

  const handleTemplateChange = (nextTemplateId: OfficialTemplateId, nextFormatId?: string) => {
    setSelectedSavedTemplateId(null);
    setSelectedSavedTemplateDocument(null);
    setTemplateId(nextTemplateId);
    setForm((current) => ({
      ...current,
      formatId: nextFormatId ?? current.formatId
    }));
    setTemplateDialogOpen(false);
  };

  const handleSavedTemplateChange = async (template: TemplateListItem) => {
    if (!session) {
      return;
    }

    setSavedTemplateLoadingId(template.id);
    try {
      const nextDocument = await fetchTemplateDocument(template.id, session);
      setSelectedSavedTemplateId(template.id);
      setSelectedSavedTemplateDocument(nextDocument);
      setSavedTemplateDialogOpen(false);
    } catch {
      setSavedTemplatesError("Nao foi possivel abrir o template salvo selecionado.");
    } finally {
      setSavedTemplateLoadingId(null);
    }
  };

  const handleReturnToOfficialTemplate = () => {
    setSelectedSavedTemplateId(null);
    setSelectedSavedTemplateDocument(null);
  };

  const handlePrint = () => {
    const scannableErrors = getScannableValidationErrors(document, previewPayload);
    if (scannableErrors.length > 0) {
      setSavedTemplatesError(scannableErrors[0] ?? "Corrija o codigo antes de imprimir.");
      return;
    }

    setPrintActive(true);
  };

  const automaticSummary = useMemo(() => {
    const manufacturedLabel = formatDateLabel(form.manufacturedAt);
    const expiresLabel = formatDateLabel(form.expiresAt);
    return `Fabricacao ${manufacturedLabel} | Validade ${expiresLabel} | Origem aplicada automaticamente.`;
  }, [form.expiresAt, form.manufacturedAt]);

  const activeFormatLabel = useMemo(() => {
    const metadataFormatId =
      selectedSavedTemplateDocument &&
      typeof selectedSavedTemplateDocument.metadata?.formatId === "string"
        ? selectedSavedTemplateDocument.metadata.formatId
        : null;

    const metadataFormat = metadataFormatId ? getLabelFormatById(metadataFormatId) : undefined;
    if (metadataFormat) {
      return metadataFormat.name;
    }

    if (selectedSavedTemplateDocument) {
      return `${selectedSavedTemplateDocument.document.width} x ${selectedSavedTemplateDocument.document.height} ${selectedSavedTemplateDocument.document.unit}`;
    }

    return selectedFormat.name;
  }, [selectedFormat.name, selectedSavedTemplateDocument]);

  return (
    <Stack spacing={3}>
      <PageSection sx={{ p: { xs: 2.25, md: 3 } }} contentSx={{ display: "grid", gap: 3 }}>
        <Stack spacing={1} sx={{ maxWidth: 720 }}>
          <Typography variant="overline" color="text.secondary">
            Operacao diaria
          </Typography>
          <Typography variant="h4">Preencha, confira a etiqueta e imprima.</Typography>
          <Typography variant="body2" color="text.secondary">
            A entrada do sistema fica centrada no uso rapido, mas o preview agora mostra o
            template oficial completo do modelo escolhido.
          </Typography>
          <Typography variant="caption" color="text.secondary">
            Modelo padrao da operacao rapida: 60x40 unidade vertical.
          </Typography>
        </Stack>

        <Box
          sx={{
            display: "grid",
            gridTemplateColumns: { xs: "1fr", lg: "minmax(300px, 360px) minmax(0, 1fr)" },
            gap: 3,
            alignItems: "start"
          }}
        >
          <Stack spacing={2.25}>
            <Stack direction="row" spacing={1} useFlexGap sx={{ flexWrap: "wrap" }}>
              {selectedSavedTemplate ? (
                <Chip
                  variant="filled"
                  color="primary"
                  icon={<BookmarkBorderRoundedIcon />}
                  label={`Template salvo: ${selectedSavedTemplate.name}`}
                />
              ) : (
                <Chip
                  variant="filled"
                  color={templateId === DEFAULT_TEMPLATE_ID ? "primary" : "default"}
                  label={
                    templateId === DEFAULT_TEMPLATE_ID
                      ? `Modelo padrao: ${selectedTemplate?.name ?? "60x40 unidade vertical"}`
                      : selectedTemplate?.name ?? "Modelo oficial"
                  }
                />
              )}
              <Button variant="text" size="small" onClick={() => setSavedTemplateDialogOpen(true)}>
                Alterar modelo
              </Button>
              <Chip variant="outlined" color="primary" label={`Etiqueta ${activeFormatLabel}`} />
              <Button variant="text" size="small" onClick={() => setFormatDialogOpen(true)}>
                Alterar formato
              </Button>
              <Button
                variant="text"
                size="small"
                onClick={() => setTemplateDialogOpen(true)}
                startIcon={<BookmarkBorderRoundedIcon />}
              >
                Modelos oficiais
              </Button>
              {selectedSavedTemplate ? (
                <Button variant="text" size="small" onClick={handleReturnToOfficialTemplate}>
                  Usar modelo oficial
                </Button>
              ) : null}
            </Stack>

            {savedTemplatesError ? <Alert severity="warning">{savedTemplatesError}</Alert> : null}

            <Autocomplete
              options={products}
              loading={productsLoading}
              filterOptions={(options) => options}
              value={selectedProduct}
              inputValue={productSearch}
              onInputChange={(_event, value, reason) => {
                if (reason === "reset") {
                  return;
                }

                setProductSearch(value);
              }}
              onChange={(_event, product) => handleProductSelection(product)}
              getOptionLabel={(product) => product?.name ?? ""}
              getOptionKey={getProductOptionKey}
              isOptionEqualToValue={(option, value) => option.id === value.id}
              loadingText="Carregando produtos da base..."
              noOptionsText={
                productsError
                  ? "Nao foi possivel carregar os produtos."
                  : debouncedProductSearch
                    ? "Nenhum produto encontrado para essa busca."
                    : "Nenhum produto ativo encontrado na base."
              }
              renderOption={(props, product) => {
                const { key, ...optionProps } = props;

                return (
                  <Box
                    component="li"
                    key={product.id ?? key ?? getProductOptionKey(product)}
                    {...optionProps}
                    sx={{ display: "grid", gap: 0.35, py: 1 }}
                  >
                    <Typography variant="body2" sx={{ fontWeight: 700 }}>
                      {product.name}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {buildProductOptionMeta(product)}
                    </Typography>
                  </Box>
                );
              }}
              renderInput={(params) => (
                <TextField
                  {...params}
                  label="Produto da base"
                  placeholder="Buscar produto cadastrado"
                  helperText={
                    productsError ??
                    "Busca por nome, codigo, barcode ou categoria. Ao selecionar, ingredientes, preco, unidade e codigo de barras entram automaticamente no template."
                  }
                />
              )}
            />

            <TextField
              label="Responsavel"
              value={form.responsible}
              onChange={(event) => handleFieldChange("responsible", event.target.value)}
              placeholder="Nome do responsavel"
              fullWidth
            />

            <TextField
              label="Item"
              value={form.product}
              onChange={(event) => handleFieldChange("product", event.target.value)}
              placeholder="Descricao do produto"
              fullWidth
            />

            <TextField
              label="Quantidade"
              type="number"
              value={form.quantity}
              onChange={(event) => handleQuantityChange(event.target.value)}
              slotProps={{ htmlInput: { min: 1, step: 1 } }}
              fullWidth
            />

            <Typography variant="caption" color="text.secondary" sx={{ lineHeight: 1.6 }}>
              {automaticSummary}
            </Typography>

            <Button
              variant="contained"
              size="large"
              startIcon={<LocalPrintshopRoundedIcon />}
              onClick={handlePrint}
              sx={{ alignSelf: "flex-start", minWidth: 176 }}
            >
              Imprimir
            </Button>
          </Stack>

          <Stack spacing={1.25}>
            <Box sx={{ display: "grid", gap: 0.5 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                Preview da etiqueta
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Atualiza em tempo real e usa a mesma base oficial da impressao.
              </Typography>
              {selectedSavedTemplate ? (
                <Typography variant="caption" color="text.secondary">
                  Base atual: template salvo atualizado em{" "}
                  {formatTimestampLabel(selectedSavedTemplate.updatedAt)}.
                </Typography>
              ) : null}
            </Box>

            <Box
              sx={{
                minHeight: 360,
                display: "grid",
                placeItems: "center",
                borderRadius: 3,
                border: "1px dashed rgba(15, 23, 42, 0.12)",
                background:
                  "linear-gradient(180deg, rgba(248,250,252,0.92), rgba(241,245,249,0.92))",
                p: { xs: 1.5, md: 2 }
              }}
            >
              <LabelPreviewSurface
                document={document}
                previewPayload={previewPayload}
                scale={previewScale}
                preset="preview"
              />
            </Box>
          </Stack>
        </Box>
      </PageSection>

      <Dialog
        open={templateDialogOpen}
        onClose={() => setTemplateDialogOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Escolher modelo oficial</DialogTitle>
        <DialogContent dividers>
          <Stack spacing={1.25}>
              {OFFICIAL_TEMPLATE_OPTIONS.map((template) => {
                const active = template.id === templateId;
                const isDefault = template.id === DEFAULT_TEMPLATE_ID;
                const previewSample = templatePreviewSamples[template.id];

                return (
                  <Button
                    key={template.id}
                    variant={active ? "contained" : "outlined"}
                    color={active ? "primary" : "inherit"}
                    onClick={() =>
                      handleTemplateChange(template.id, template.defaultFormat?.id)
                    }
                    sx={{
                      justifyContent: "space-between",
                      textAlign: "left",
                      px: 2,
                      py: 1.5
                    }}
                  >
                    <Stack
                      direction="row"
                      spacing={1.5}
                      sx={{
                        width: "100%",
                        alignItems: "center",
                        justifyContent: "space-between"
                      }}
                    >
                      <Stack spacing={0.5} sx={{ alignItems: "flex-start", minWidth: 0, flex: 1 }}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: "center", flexWrap: "wrap" }}>
                          <Typography variant="subtitle2">{template.name}</Typography>
                          {isDefault ? (
                            <Chip
                              size="small"
                              color={active ? "default" : "primary"}
                              variant={active ? "filled" : "outlined"}
                              label="Padrao"
                            />
                          ) : null}
                        </Stack>
                        <Typography variant="caption" sx={{ color: "inherit", opacity: 0.82 }}>
                          {template.summary}
                        </Typography>
                      </Stack>

                      <Box
                        sx={{
                          flexShrink: 0,
                          width: 148,
                          minWidth: 148,
                          display: { xs: "none", sm: "grid" },
                          placeItems: "center",
                          borderRadius: 2,
                          border: "1px solid",
                          borderColor: active ? "rgba(255,255,255,0.28)" : "divider",
                          background: active
                            ? "rgba(255,255,255,0.1)"
                            : "linear-gradient(180deg, rgba(248,250,252,0.95), rgba(241,245,249,0.95))",
                          py: 1,
                          px: 0.75
                        }}
                      >
                        <LabelPreviewSurface
                          document={previewSample.document}
                          previewPayload={previewSample.previewPayload}
                          scale={previewSample.scale}
                          preset="preview"
                          containerStyle={{ marginInline: "auto" }}
                          surfaceStyle={{
                            borderRadius: 8,
                            boxShadow: active
                              ? "0 10px 20px rgba(15, 23, 42, 0.18)"
                              : "0 8px 18px rgba(15, 23, 42, 0.08)"
                          }}
                        />
                      </Box>
                    </Stack>
                  </Button>
              );
            })}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setTemplateDialogOpen(false)}>Fechar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={formatDialogOpen}
        onClose={() => setFormatDialogOpen(false)}
        fullWidth
        maxWidth="md"
      >
        <DialogTitle>Escolher formato da etiqueta</DialogTitle>
        <DialogContent dividers>
          <LabelFormatSelector
            categories={LABEL_FORMAT_CATEGORIES}
            formats={LABEL_FORMATS}
            value={form.formatId}
            onChange={handleFormatChange}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setFormatDialogOpen(false)}>Fechar</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={savedTemplateDialogOpen}
        onClose={() => setSavedTemplateDialogOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Alterar modelo</DialogTitle>
        <DialogContent dividers>
          {savedTemplatesLoading ? (
            <Stack spacing={1.5} sx={{ alignItems: "center", py: 4 }}>
              <CircularProgress size={26} />
              <Typography variant="body2" color="text.secondary">
                Carregando templates salvos...
              </Typography>
            </Stack>
          ) : savedTemplates.length === 0 ? (
            <Alert severity="info">
              Nenhum template salvo foi encontrado nos ultimos modelos criados.
            </Alert>
          ) : (
            <Stack spacing={1.25}>
              {savedTemplates.map((template) => {
                const active = template.id === selectedSavedTemplateId;

                return (
                  <Button
                    key={template.id}
                    variant={active ? "contained" : "outlined"}
                    color={active ? "primary" : "inherit"}
                    disabled={savedTemplateLoadingId === template.id}
                    onClick={() => void handleSavedTemplateChange(template)}
                    sx={{
                      justifyContent: "flex-start",
                      textAlign: "left",
                      px: 2,
                      py: 1.5
                    }}
                    >
                    <Stack spacing={0.5} sx={{ alignItems: "flex-start" }}>
                      <Typography variant="subtitle2">{template.name}</Typography>
                      <Typography variant="caption" sx={{ color: "inherit", opacity: 0.82 }}>
                        {formatTemplateCategoryLabel(template)} | {formatTemplateTypeLabel(template)}
                      </Typography>
                      <Typography variant="caption" sx={{ color: "inherit", opacity: 0.82 }}>
                        Status {template.status} | Atualizado em{" "}
                        {formatTimestampLabel(template.updatedAt)}
                      </Typography>
                    </Stack>
                  </Button>
                );
              })}
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSavedTemplateDialogOpen(false)}>Fechar</Button>
        </DialogActions>
      </Dialog>

      <QuickHomePrintPortal
        active={printActive}
        document={document}
        previewPayload={previewPayload}
        quantity={form.quantity}
      />
    </Stack>
  );
}

function QuickHomePrintPortal({
  active,
  document,
  previewPayload,
  quantity
}: {
  active: boolean;
  document: LabelDocument;
  previewPayload: PreviewPayload;
  quantity: number;
}) {
  if (!active) {
    return null;
  }

  const copies = Math.max(1, Math.floor(quantity || 1));

  return (
    <LabelPrintPortal>
      <div className="label-print-portal">
        <div data-print-root className="label-print-root">
          {Array.from({ length: copies }, (_, index) => (
            <div
              key={`quick-print-${index}`}
              className="label-print-root__page"
              style={{
                breakAfter: index < copies - 1 ? "page" : "auto",
                pageBreakAfter: index < copies - 1 ? "always" : "auto"
              }}
            >
              <div className="label-print-root__item">
                <div className="label-print-surface">
                  <LabelPreviewSurface
                    document={document}
                    previewPayload={previewPayload}
                    scale={1}
                    preset="print"
                    mode="physical"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </LabelPrintPortal>
  );
}
