import type {
  BarcodeElement,
  LabelDocument,
  LabelElement,
  TextElement
} from "@easyprint/shared/template/document";
import type { PreviewPayload } from "@easyprint/shared/template/render";
import { getDefaultLabelFormat, listFormats, type LabelFormat } from "./label-format-registry";
import type { LabelFormat as RegistryLabelFormat } from "./label-format-registry";
import { getTypography } from "./label-typography";

export type QuickLabelForm = {
  formatId: string;
  responsible: string;
  product: string;
  quantity: number;
  manufacturedAt: string;
  expiresAt: string;
  barcode: string;
};

const FOOTER_LINES = [
  "Pascal Fast Food.",
  "Rua Victorio Viezzer, 588. Vista Alegre. Curitiba - Parana."
];

const baseText = (overrides: Partial<TextElement>): TextElement => ({
  id: overrides.id ?? "text",
  type: "text",
  name: overrides.name ?? "text",
  x: overrides.x ?? 0,
  y: overrides.y ?? 0,
  width: overrides.width ?? 20,
  height: overrides.height ?? 6,
  rotation: 0,
  visible: true,
  locked: false,
  zIndex: overrides.zIndex ?? 1,
  contentMode: overrides.contentMode ?? "static",
  text: overrides.text ?? "",
  bindingKey: overrides.bindingKey,
  placeholder: overrides.placeholder,
  fontSize: overrides.fontSize ?? getTypography("product").fontSize,
  fontFamily: overrides.fontFamily ?? "Inter",
  fontWeight: overrides.fontWeight ?? getTypography("product").fontWeight ?? 600,
  fontStyle: overrides.fontStyle ?? "normal",
  textDecoration: overrides.textDecoration ?? "none",
  lineHeight: overrides.lineHeight ?? 1.2,
  color: overrides.color ?? "#0f172a",
  align: overrides.align ?? "left"
});

const baseBarcode = (overrides: Partial<BarcodeElement>): BarcodeElement => ({
  id: overrides.id ?? "barcode",
  type: "barcode",
  name: overrides.name ?? "barcode",
  x: overrides.x ?? 0,
  y: overrides.y ?? 0,
  width: overrides.width ?? 30,
  height: overrides.height ?? 14,
  rotation: 0,
  visible: true,
  locked: false,
  zIndex: overrides.zIndex ?? 5,
  value: overrides.value ?? "123456789012",
  format: overrides.format ?? "CODE128",
  showHumanReadable: overrides.showHumanReadable ?? true
});

const computeLayout = (format: RegistryLabelFormat) => {
  const margin = 3;
  const width = format.widthMm;
  const height = format.heightMm;
  const halfWidth = Math.max(22, (width - margin * 3) / 2);

  const titleY = margin;
  const productY = titleY + 8.5;
  const infoY = productY + 11.5;
  const valueY = infoY + 6;
  const datesY = valueY + 9;
  const barcodeHeight = 14;
  const barcodeY = Math.max(datesY + 10, height - barcodeHeight - 13);
  const footerY = Math.min(height - 9, barcodeY + barcodeHeight + 3);

  return {
    width,
    height,
    title: { x: margin, y: titleY, width: width - margin * 2, height: 7.5 },
    product: { x: margin, y: productY, width: width - margin * 2, height: 9.5 },
    responsibleLabel: { x: margin, y: infoY, width: halfWidth, height: 4.5 },
    responsible: { x: margin, y: valueY, width: halfWidth, height: 7.5 },
    quantityLabel: {
      x: margin * 2 + halfWidth,
      y: infoY,
      width: width - halfWidth - margin * 3,
      height: 4.5
    },
    quantity: {
      x: margin * 2 + halfWidth,
      y: valueY,
      width: width - halfWidth - margin * 3,
      height: 7.5
    },
    manufactured: { x: margin, y: datesY, width: halfWidth, height: 7 },
    expires: {
      x: margin * 2 + halfWidth,
      y: datesY,
      width: width - halfWidth - margin * 3,
      height: 7
    },
    barcode: { x: margin, y: barcodeY, width: width - margin * 2, height: barcodeHeight },
    footerY
  };
};

export function buildQuickLabelDocument(
  form: QuickLabelForm,
  format: LabelFormat = getDefaultLabelFormat()
): LabelDocument {
  const layout = computeLayout(format);

  const elements: LabelElement[] = [
    baseText({
      id: "title",
      name: "Titulo",
      text: "Etiqueta",
      x: layout.title.x,
      y: layout.title.y,
      width: layout.title.width,
      height: layout.title.height,
      fontSize: getTypography("title").fontSize,
      fontWeight: getTypography("title").fontWeight,
      zIndex: 1
    }),
    baseText({
      id: "product",
      name: "Produto",
      contentMode: "dynamic",
      bindingKey: "product",
      text: "Item",
      x: layout.product.x,
      y: layout.product.y,
      width: layout.product.width,
      height: layout.product.height,
      fontSize: getTypography("product").fontSize,
      fontWeight: getTypography("product").fontWeight,
      zIndex: 2
    }),
    baseText({
      id: "responsible-label",
      name: "Responsavel label",
      text: "Responsavel",
      x: layout.responsibleLabel.x,
      y: layout.responsibleLabel.y,
      width: layout.responsibleLabel.width,
      height: layout.responsibleLabel.height,
      fontSize: getTypography("responsibleLabel").fontSize,
      fontWeight: getTypography("responsibleLabel").fontWeight,
      zIndex: 3
    }),
    baseText({
      id: "responsible",
      name: "Responsavel",
      contentMode: "dynamic",
      bindingKey: "responsible",
      text: "Responsavel",
      x: layout.responsible.x,
      y: layout.responsible.y,
      width: layout.responsible.width,
      height: layout.responsible.height,
      fontSize: getTypography("responsibleName").fontSize,
      fontWeight: getTypography("responsibleName").fontWeight,
      zIndex: 4
    }),
    baseText({
      id: "quantity-label",
      name: "Quantidade label",
      text: "Quantidade",
      x: layout.quantityLabel.x,
      y: layout.quantityLabel.y,
      width: layout.quantityLabel.width,
      height: layout.quantityLabel.height,
      fontSize: getTypography("responsibleLabel").fontSize,
      fontWeight: getTypography("responsibleLabel").fontWeight,
      align: "right",
      zIndex: 3
    }),
    baseText({
      id: "quantity",
      name: "Quantidade",
      contentMode: "dynamic",
      bindingKey: "quantity",
      text: "1",
      x: layout.quantity.x,
      y: layout.quantity.y,
      width: layout.quantity.width,
      height: layout.quantity.height,
      fontSize: getTypography("responsibleName").fontSize,
      fontWeight: getTypography("responsibleName").fontWeight,
      align: "right",
      zIndex: 4
    }),
    baseText({
      id: "manufactured",
      name: "Fabricacao",
      contentMode: "dynamic",
      bindingKey: "manufacturedAt",
      text: "Fabricacao",
      x: layout.manufactured.x,
      y: layout.manufactured.y,
      width: layout.manufactured.width,
      height: layout.manufactured.height,
      fontSize: 8,
      fontWeight: 600,
      zIndex: 4
    }),
    baseText({
      id: "expires",
      name: "Validade",
      contentMode: "dynamic",
      bindingKey: "expiresAt",
      text: "Validade",
      x: layout.expires.x,
      y: layout.expires.y,
      width: layout.expires.width,
      height: layout.expires.height,
      fontSize: 8,
      fontWeight: 600,
      align: "right",
      zIndex: 4
    }),
    baseBarcode({
      id: "barcode",
      name: "Codigo de barras",
      value: form.barcode || "123456789012",
      x: layout.barcode.x,
      y: layout.barcode.y,
      width: layout.barcode.width,
      height: layout.barcode.height
    }),
    baseText({
      id: "footer-1",
      name: "Origem linha 1",
      text: FOOTER_LINES[0],
      x: 3,
      y: layout.footerY,
      width: layout.width - 6,
      height: 5,
      fontSize: 6.2,
      fontWeight: 600
    }),
    baseText({
      id: "footer-2",
      name: "Origem linha 2",
      text: FOOTER_LINES[1],
      x: 3,
      y: layout.footerY + 5.8,
      width: layout.width - 6,
      height: 5,
      fontSize: 6,
      fontWeight: 600
    })
  ];

  const dataSchema = [
    { key: "product", label: "Produto", type: "text" as const, required: true },
    { key: "responsible", label: "Responsavel", type: "text" as const, required: true },
    { key: "quantity", label: "Quantidade", type: "number" as const, required: true },
    { key: "manufacturedAt", label: "Fabricacao", type: "date" as const, required: true },
    { key: "expiresAt", label: "Validade", type: "date" as const, required: true },
    { key: "barcode", label: "Codigo de barras", type: "text" as const, required: true }
  ];

  return {
    id: `quick-${format.id}`,
    name: `Etiqueta ${format.name}`,
    version: 1,
    status: "draft",
    document: {
      width: format.widthMm,
      height: format.heightMm,
      unit: "mm",
      orientation: format.widthMm >= format.heightMm ? "landscape" : "portrait",
      background: "#ffffff",
      dpi: 203
    },
    settings: {},
    dataSchema,
    elements,
    metadata: {
      formatId: format.id,
      shape: format.shape,
      category: format.category
    }
  };
}

export function buildQuickPreviewPayload(form: QuickLabelForm): PreviewPayload {
  return {
    product: form.product,
    responsible: form.responsible,
    quantity: String(form.quantity),
    manufacturedAt: form.manufacturedAt,
    expiresAt: form.expiresAt,
    barcode: form.barcode
  };
}

export const getDefaultQuickForm = (): QuickLabelForm => {
  const defaultFormat = getDefaultLabelFormat();
  const today = new Date();
  const manufactured = new Date(today.getTime() - today.getTimezoneOffset() * 60000)
    .toISOString()
    .slice(0, 10);
  const expires = new Date(today.getTime() - today.getTimezoneOffset() * 60000);
  expires.setDate(expires.getDate() + 2);
  const expiresStr = expires.toISOString().slice(0, 10);

  return {
    formatId: defaultFormat.id,
    responsible: "",
    product: "",
    quantity: 1,
    manufacturedAt: manufactured,
    expiresAt: expiresStr,
    barcode: "123456789012"
  };
};

export const listFormatOptions = () =>
  listFormats().map((format) => ({
    value: format.id,
    label: format.name,
    category: format.category,
    description: format.description
  }));
