"use client";

import type { CSSProperties, ReactNode } from "react";
import {
  type LabelDocument,
  type LabelElement,
  type TextElement
} from "@easyprint/shared/template/document";
import {
  getBarcodeMinimumSize,
  normalizeBarcodeText,
  validateBarcodeValue,
  validateQrCodeValue
} from "@easyprint/shared/template/barcode";
import {
  buildPreviewPayload,
  type PreviewPayload,
  resolveFieldPreviewValue,
  resolveTextElementContent
} from "@easyprint/shared/template/render";
import { getTextElementStyle } from "../../lib/editor-text";
import { BarcodeSymbol } from "./barcode-symbol";
import { QrSymbol } from "./qr-symbol";

const sizeValue = (value: number, scale: number, useMm: boolean) =>
  useMm ? `${value}mm` : value * scale;

export const getElementFrameStyle = (
  element: LabelElement,
  scale: number,
  usePhysicalUnits: boolean,
  extra?: CSSProperties
): CSSProperties => ({
  position: "absolute",
  left: sizeValue(element.x, scale, usePhysicalUnits),
  top: sizeValue(element.y, scale, usePhysicalUnits),
  width: sizeValue(element.width, scale, usePhysicalUnits),
  height: sizeValue(element.height, scale, usePhysicalUnits),
  transform: `rotate(${element.rotation}deg)`,
  transformOrigin: "center center",
  display: element.visible ? "block" : "none",
  ...extra
});

export function LabelElementContent({
  document,
  element,
  scale = 1,
  previewPayload = buildPreviewPayload(document),
  usePhysicalUnits = false,
  textOverride,
  textChildren
}: {
  document: LabelDocument;
  element: LabelElement;
  scale?: number;
  previewPayload?: PreviewPayload;
  usePhysicalUnits?: boolean;
  textOverride?: string;
  textChildren?: ReactNode;
}) {
  if (element.type === "text") {
    const content =
      textOverride ?? resolveTextElementContent(document, element, previewPayload);

    return (
      <div style={getTextElementStyle(element as TextElement, scale, { physical: usePhysicalUnits })}>
        {textChildren ?? content}
      </div>
    );
  }

  if (element.type === "shape") {
    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          background: element.fill,
          border: `${Math.max(1, element.strokeWidth * scale)}px solid ${element.stroke}`,
          borderRadius: element.borderRadius * scale
        }}
      />
    );
  }

  if (element.type === "line") {
    return (
      <div
        style={{
          width: "100%",
          height: Math.max(1, element.strokeWidth * scale),
          background: element.stroke,
          marginTop: Math.max(0, element.height * scale / 2 - Math.max(1, element.strokeWidth * scale) / 2)
        }}
      />
    );
  }

  if (element.type === "barcode") {
    const rawValue = element.bindingKey
      ? String(resolveFieldPreviewValue(document, element.bindingKey, previewPayload) || element.value)
      : element.value;
    const resolvedValue = normalizeBarcodeText(element.format, rawValue);
    const validation = validateBarcodeValue(element.format, resolvedValue);
    const minimumSize = getBarcodeMinimumSize(element.format);
    const sizeWarning =
      element.width < minimumSize.widthMm || element.height < minimumSize.heightMm
        ? `Minimo recomendado: ${minimumSize.widthMm} x ${minimumSize.heightMm} mm.`
        : null;

    if (!validation.valid) {
      return (
        <div
          style={{
            width: "100%",
            height: "100%",
            display: "grid",
            placeItems: "center",
            padding: usePhysicalUnits ? "1mm" : Math.max(4, scale * 0.6),
            border: `${usePhysicalUnits ? "0.25mm" : Math.max(1, scale * 0.3)} solid #b91c1c`,
            background: "#fff5f5",
            color: "#991b1b",
            fontSize: usePhysicalUnits ? "2.2mm" : Math.max(8, scale * 1.2),
            fontWeight: 700,
            lineHeight: 1.15,
            textAlign: "center",
            boxSizing: "border-box"
          }}
        >
          {validation.message}
        </div>
      );
    }

    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "block",
          background: "#ffffff",
          border: sizeWarning
            ? `${usePhysicalUnits ? "0.2mm" : Math.max(1, scale * 0.25)} solid #d97706`
            : "none",
          boxSizing: "border-box"
        }}
        title={sizeWarning ?? undefined}
      >
        <BarcodeSymbol
          value={resolvedValue}
          format={element.format}
          showHumanReadable={element.showHumanReadable}
          physical={usePhysicalUnits}
        />
      </div>
    );
  }

  if (element.type === "qrcode") {
    const validation = validateQrCodeValue(element.value);
    if (!validation.valid) {
      return (
        <div
          style={{
            width: "100%",
            height: "100%",
            display: "grid",
            placeItems: "center",
            padding: usePhysicalUnits ? "1mm" : Math.max(4, scale * 0.6),
            border: `${usePhysicalUnits ? "0.25mm" : Math.max(1, scale * 0.3)} solid #b91c1c`,
            background: "#fff5f5",
            color: "#991b1b",
            fontSize: usePhysicalUnits ? "2.2mm" : Math.max(8, scale * 1.2),
            fontWeight: 700,
            textAlign: "center",
            boxSizing: "border-box"
          }}
        >
          {validation.message}
        </div>
      );
    }

    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          padding: Math.max(2, scale * 0.4),
          background: "#ffffff",
          border: `${Math.max(1, scale * 0.35)}px solid #111827`
        }}
      >
        <QrSymbol value={element.value} level={element.errorCorrection} />
      </div>
    );
  }

  if (element.type === "image") {
    const objectFit =
      element.objectFit ?? (element.fit === "stretch" ? "fill" : element.fit);

    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          border: element.src ? "none" : `${Math.max(1, scale * 0.35)}px dashed #94a3b8`,
          display: "grid",
          placeItems: "center",
          color: "#64748b",
          background: element.src ? "transparent" : "rgba(148, 163, 184, 0.08)",
          opacity: element.opacity,
          overflow: "hidden",
          boxSizing: "border-box"
        }}
      >
        {element.src ? (
          <img
            src={element.src}
            alt={element.name}
            draggable={false}
            style={{
              width: "100%",
              height: "100%",
              display: "block",
              objectFit,
              userSelect: "none",
              pointerEvents: "none"
            }}
          />
        ) : (
          "Imagem"
        )}
      </div>
    );
  }

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        border: `${Math.max(1, scale * 0.35)}px dashed #94a3b8`,
        display: "grid",
        placeItems: "center",
        color: "#64748b",
        background: "rgba(148, 163, 184, 0.08)"
      }}
    >
      Elemento
    </div>
  );
}

export function LabelDocumentSurface({
  document,
  scale,
  previewPayload = buildPreviewPayload(document),
  containerStyle,
  surfaceStyle,
  renderElement,
  mode = "screen"
}: {
  document: LabelDocument;
  scale: number;
  previewPayload?: PreviewPayload;
  containerStyle?: CSSProperties;
  surfaceStyle?: CSSProperties;
  renderElement?: (element: LabelElement, content: ReactNode) => ReactNode;
  mode?: "screen" | "physical";
}) {
  const usePhysicalUnits = mode === "physical" && document.document.unit === "mm";

  return (
    <div
      style={{
        position: "relative",
        width: usePhysicalUnits ? `${document.document.width}mm` : document.document.width * scale,
        height: usePhysicalUnits ? `${document.document.height}mm` : document.document.height * scale,
        ...containerStyle
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: document.document.background,
          overflow: "hidden",
          ...surfaceStyle
        }}
      >
        {[...document.elements]
          .sort((left, right) => left.zIndex - right.zIndex)
          .map((element) => {
            const content = (
              <div key={element.id} style={getElementFrameStyle(element, scale, usePhysicalUnits)}>
                <LabelElementContent
                  document={document}
                  element={element}
                  scale={scale}
                  previewPayload={previewPayload}
                  usePhysicalUnits={usePhysicalUnits}
                />
              </div>
            );

            return renderElement ? renderElement(element, content) : content;
          })}
      </div>
    </div>
  );
}
